use anyhow::{bail, Result};
use unicodex_core::{cid_for_bytes, decode_node, Node, ObjectStore};

use super::{ensure_program_module_value, module_program_cid};

#[derive(Debug, Clone)]
pub(super) struct ResolvedModuleEntry {
    pub(super) module_name: String,
    pub(super) entry: String,
    pub(super) program_cid: String,
}

pub(super) fn resolve_module_entry(
    store: &ObjectStore,
    module_cid: &str,
    entry_override: Option<&str>,
) -> Result<ResolvedModuleEntry> {
    let canonical = store.get_canonical(module_cid)?;
    if cid_for_bytes(&canonical) != module_cid {
        bail!("program module hash mismatch");
    }
    let value = match decode_node(&canonical)? {
        Node::Value(value) => value,
        _ => bail!("{module_cid} is not a value node"),
    };
    let fields = ensure_program_module_value(&value)?;
    let entry = entry_override.unwrap_or(fields.entry.as_str());
    if entry.trim().is_empty() {
        bail!("program module entry override must not be empty");
    }
    Ok(ResolvedModuleEntry {
        module_name: fields.name,
        entry: entry.to_owned(),
        program_cid: module_program_cid(&value, entry)?.to_owned(),
    })
}

